<?php namespace Agah\Erp\Http;use Agah\Erp\Core\{Money,Jalali,Ctx};use Agah\Erp\Modules\Manufacturing\ProductionService;if(!defined('ABSPATH'))exit; ?>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>شماره / تاریخ</th><th>محصول</th><th>برنامه / واقعی</th><th>وضعیت</th><th>مواد</th><th>دستمزد / سربار</th><th>ضایعات غیرعادی</th><th>بهای محصول</th></tr></thead><tbody><?php foreach($data['rows'] as $o):$snap=json_decode($o['snapshot'],true); ?><tr><td><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'production_order','id'=>$o['id']])); ?>"><?php echo esc_html(Money::toFa($o['number']).' / '.Jalali::format($o['doc_date'])); ?></a></td><td><?php echo esc_html(($snap['product_code']??'').' — '.($snap['product_name']??'')); ?></td><td><?php echo esc_html(Money::qtyToDb((int)$o['planned_qty']).' / '.Money::qtyToDb((int)$o['actual_qty'])); ?></td><td><?php echo esc_html(ProductionService::STATES[$o['status']]??$o['status']); ?></td><?php foreach(['material_cost','labor_cost','abnormal_cost','total_cost'] as $key): ?><td><?php echo esc_html(Money::fmt((int)$o[$key],Ctx::unit()));if($key==='labor_cost')echo ' / '.esc_html(Money::fmt((int)$o['overhead_cost'],Ctx::unit())); ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
